import{_ as s,a0 as u,w as a,s as l,ao as p,I as r,x as e,a1 as o,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"使用6款卓尔不群的Linux操作系统为你的上网本添活力 | LCTT x X-CMD","titleTemplate":false,"description":"使用6款卓尔不群的Linux操作系统为你的上网本添活力 | LCTT (201402) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用6款卓尔不群的Linux操作系统为你的上网本添活力 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用6款卓尔不群的Linux操作系统为你的上网本添活力 | LCTT (201402) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201402/6 Unusual Yet Great Linux Operating Systems For Your Netbook!","title":"使用6款卓尔不群的Linux操作系统为你的上网本添活力","tag":"201402","desc":""},"relativePath":"201402/6 Unusual Yet Great Linux Operating Systems For Your Netbook!.md","filePath":"[post].md"}'),m={name:"201402/6 Unusual Yet Great Linux Operating Systems For Your Netbook!.md"};function d(x,t,L,g,f,T){const n=u("Link");return a(),l("div",null,[t[11]||(t[11]=p('<h1 id="使用6款卓尔不群的linux操作系统为你的上网本添活力" tabindex="-1">使用6款卓尔不群的Linux操作系统为你的上网本添活力 <a class="header-anchor" href="#使用6款卓尔不群的linux操作系统为你的上网本添活力" aria-label="Permalink to “使用6款卓尔不群的Linux操作系统为你的上网本添活力”">​</a></h1><blockquote><p>基于Linux的操作系统的优点是它们可以根据不同的需求定制。因此，在这里我们将为您呈现6款专为上网本设计不同于其它而又有趣的顶尖发行版。</p></blockquote><p>评定一款上网本的OS是否良好，主要取决于它能否“物尽其用”。当在闲置模式下,内存使用应该降到最小限度，你需要一个很好的导航系统来避免屏幕的错乱。</p><p>对于一名 Linux 爱好者来说，拥有一款对本本优化过的操作系统，同时还是基于开源技术，这该有多好啊。</p><p><img src="http://1-ps.googleusercontent.com/h/www.efytimes.com/admin/useradmin/photo/150x150xlU3z33744PM1132014.jpg.pagespeed.ic.3AoI0od5vQ.jpg" alt=""></p><ol><li><p><strong>AntiX</strong> - 利用了 iceWM 窗口管理器，能帮助维持初始内存的低占用。虽然它并不像 Ubuntu, Mint 和 Elementary 那样风靡，但是它功能齐全。在底部有一个导航任务栏，桌面上的标准跨操作系统图标已经存在数年之久。AntiX 带有一系列的应用程序，其中有少部分不太适合用于上网本。</p></li><li><p><strong>SparkyLinux</strong> - Razor-Qt 的外观和体验是非常传统的，底部有一个面板，菜单位于底部的左下角。SparkyLinux 带有一系列应用程序。开发者再次选择了 LibreOffice 套件，而不是更加轻量的 Abiword 和 Gnumeric 工具包。</p></li><li><p><strong>Lubuntu</strong> - LXDE 桌面非常的轻量，也近乎 Xubuntu 那么容易定制。这桌面在熟悉不过了，在底部有一个面板带有菜单和系统托盘图标。不过，你可以根据自己需要多面板自定义 Lubuntu 外观。Sylpheed 邮件客户端，火狐浏览器，以及 Abiword 和 Gnumeric ，这些应用程序对于上网本来说在合适不过了。</p></li><li><p><strong>OS4</strong> - 基于 Xubuntu。使用了 XFCE 桌面，完美定制，你可以尝试任何一种方式来工作。XFCE 是一款轻量级的桌面环境，在上网本上运行极佳。然而，你需要安装额外的限制包来播放 Flash 视频和 MP3 , 但是OS4会让这些立马工作。同时安装有 Commodore Amiga 模拟器，你如果喜欢在你的上网本上尝试一款经典复古游戏，这是个再好不过的选项。</p></li><li><p><strong>Point Linux</strong> - 它使用了MATE桌面，使它变得更加独特。MATE 桌面最初源于 GNOME2 ,但是现在它已经凭借自身发展成一个真正优秀的桌面环境。Point Linux 外观看起来非常时尚。菜单看起来非常好，在上网本上的执行效率也很高。类似于 LXDE 和 XFCE 桌面，它也有很高的定制性。Point Linux 默认带有 4 个虚拟工作区，允许你最大限度的使用你的上网本，因此它受到内存和处理器处理显示问题的限制。</p></li><li><p><strong>Elementary OS</strong> - 如果你在寻找一些非常时尚的东西，那么这款绝对适合你。它没有安装 Office 套件，但是你可以挑选你想要的工具。对于网页浏览器你可以用 Midori，邮件客户端可以用 Geary。安装有用来观看视频的 Totem 以及一款名为 Noise的紧凑型音频应用程序。</p></li></ol><p>来源： eyerydaylinuxuser.com</p><hr>',8)),r("p",null,[t[1]||(t[1]=e("via: ",-1)),o(n,{href:"http://www.efytimes.com/e1/fullnews.asp?edid=126643"},{default:i(()=>[...t[0]||(t[0]=[e("http://www.efytimes.com/e1/fullnews.asp?edid=126643",-1)])]),_:1})]),r("p",null,[t[4]||(t[4]=e("译者：",-1)),o(n,{href:"https://github.com/Luoxcat"},{default:i(()=>[...t[2]||(t[2]=[e("Luoxcat",-1)])]),_:1}),t[5]||(t[5]=e(" 校对：",-1)),o(n,{href:"https://github.com/carolinewuyan"},{default:i(()=>[...t[3]||(t[3]=[e("Caroline",-1)])]),_:1})]),r("p",null,[t[8]||(t[8]=e("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原创翻译，",-1)),o(n,{href:"http://linux.cn/"},{default:i(()=>[...t[7]||(t[7]=[e("Linux中国",-1)])]),_:1}),t[10]||(t[10]=e(" 荣誉推出",-1))])])}const _=s(m,[["render",d]]);export{y as __pageData,_ as default};
